	if !shapeValid {
		return problems
	}
	want, _ := fixNecessityFromReason(r)
	if fd.FixNecessity != want {
		if want == "" {
			add("fix_necessity_reason では必要度が決まらない (undecided がある) のに、fix_necessity %q があります", fd.FixNecessity)
----
			if (fd.PremiseCheck.Stages == "none") != (fd.PremiseCheck.Result == "skipped") {
				add("%s: stages が none のときだけ result は skipped (stages %q / result %q)",
					fn, fd.PremiseCheck.Stages, fd.PremiseCheck.Result)
			}
			for _, m := range recordPriorDefectProblems(priorDefectRequired, fd) {
				add("%s: %s", fn, m)
			}
			for _, m := range recordFixNecessityProblems(fixNecessityRequired, run.MinFixNecessity, fd) {
				add("%s: %s", fn, m)
			}
		}

		// 足すはずの下限未満の指摘は、最後の回についてだけ検査する。前の回の findings は後から
		// 書き換えない (record-schema.md の「スキーマ」) ので、報告しても直せない。足し忘れは、
		// その回を書いた直後の検査 (その回が最後の回のとき) で報告される。
		if ri == len(doc.Runs)-1 {
			for _, m := range recordPriorBelowMinimumProblems(doc, ri) {
				add("%s: %s", rn, m)
			}
		}

		problemIDs := map[string]bool{}
		for _, pl := range run.Plans {
			if pl.ProblemID != "" && problemIDs[pl.ProblemID] {
				add("%s: problem_id %q が重複しています", rn, pl.ProblemID)
			}
----
			}
		}
	}
	if !hasBelowMinimum {
		return
	}
	b.WriteString("\n## 下限未満の指摘\n")
	entries := belowMinimumEntries(doc, len(doc.Runs))
	remaining := 0
	for _, necessity := range []string{"must", "should", "could"} {
		var rows []*belowMinimumEntry
		for _, e := range entries {
			if !e.resolved && e.finding.FixNecessity == necessity {
				rows = append(rows, e)
			}
		}
		if len(rows) == 0 {
			continue
		}
		remaining += len(rows)
		fmt.Fprintf(b, "\n### %s (%d 件)\n\n", fixNecessityJa(necessity), len(rows))
		b.WriteString("| 判定した回 | 指摘 | 回避策 | また報告された回 |\n")
		b.WriteString("| --- | --- | --- | --- |\n")
		for _, e := range rows {
			b.WriteString(recordRow(renderBelowMinimumCells(e)))
		}
	}
	if remaining == 0 {
		b.WriteString("\n残っている下限未満の指摘はありません (後の回で判定し直したか、採択にしたか、採択した問題と一緒に直した)。\n")
	}
}

// renderBelowMinimumCells は節「下限未満の指摘」の 1 行のセルのスライスを返す。
